#!/bin/sh
# Goal: Fix Tailwind CSS v3.0 configuration
# Plan:
# 1. The `purge` option in Tailwind CSS has been renamed to `content` in v3.0. 
# 2. The `darkMode` option is now set to `media` by default, and its explicit declaration is no longer necessary unless we want to set it to `class`.
# 3. Update the tailwind.config.js file to reflect these changes.

cat << 'EOF' > tailwind.config.js
export default {
  content: ['./**/*.html', './**/*.js', './**/*.jsx', './**/*.tsx', './**/*.ts'],
  theme: {
    extend: {},
  },
  variants: {
    extend: {},
  },
  plugins: [],
}
EOF

echo "Tailwind CSS configuration has been updated for v3.0. The content and darkMode options are now properly set."

#!/bin/sh
# Goal: Optimize Tailwind CSS v3.0 configuration
# Plan:
# 1. The `content` option should include only relevant source files to optimize the build process.
# 2. Update the `content` paths in the tailwind.config.js file to include only the `src` directory.

cat << 'EOF' > tailwind.config.js
export default {
  content: ['./src/**/*.html', './src/**/*.js', './src/**/*.jsx', './src/**/*.tsx', './src/**/*.ts'],
  theme: {
    extend: {},
  },
  variants: {
    extend: {},
  },
  plugins: [],
}
EOF

echo "Tailwind CSS configuration has been optimized for faster builds. The content option now includes only the source files in the 'src' directory."
